"""
VulnForge CVE Matcher
Cross-references detected service products/versions (from the port scanner)
against two offline datasets, with no API key or network call at scan time:

  * data/cve_db.json    small hand-curated set (substring product match,
                        single min/max range, optional public-PoC references)
  * data/cve_feed.json  generated by `vulnforge.py cve-update` from NVD and CISA
                        KEV (CPE product match, exact version ranges, KEV flag)

Version matching is only as good as the banner. Distro packages backport
security fixes without changing the upstream version, so matches on
Ubuntu/Debian/RHEL-style builds are downgraded in confidence rather than
reported as fact.
"""
import json
import logging
import re
from pathlib import Path
from typing import Any

from .confidence import looks_distro_packaged

logger = logging.getLogger("vulnforge.cve_matcher")

# CPE products that exist under several vendors; for these the vendor must agree too.
GENERIC_PRODUCTS = {"http_server", "server", "httpd", "database", "web_server"}
# nmap's CPE vendor differs from NVD's for some products.
VENDOR_ALIASES = {"igor_sysoev": "f5", "oracle": "mysql", "mysql": "oracle", "vsftpd_project": "beasts"}


def _parse_version(version: str) -> tuple[int, ...] | None:
    """
    Leading dotted version as a tuple. A bare trailing letter becomes an extra
    component so '1.0.1f' < '1.0.1g'; portable-style 'p1' suffixes are ignored
    ('7.4p1' -> (7, 4)).
    """
    if not version:
        return None
    text = version.strip()
    match = re.match(r"^\d+(?:\.\d+)*", text)
    if not match:
        return None
    try:
        parts = tuple(int(p) for p in match.group(0).split("."))
    except ValueError:
        return None
    letter = re.match(r"([a-z])(?![a-z0-9])", text[match.end():], re.I)
    if letter:
        parts += (ord(letter.group(1).lower()) - 96,)
    return parts


def _version_cmp(a: tuple[int, ...], b: tuple[int, ...]) -> int:
    """Compare two version tuples, padding the shorter with zeros. -1/0/1."""
    length = max(len(a), len(b))
    a = a + (0,) * (length - len(a))
    b = b + (0,) * (length - len(b))
    if a < b:
        return -1
    if a > b:
        return 1
    return 0


def in_range(detected: tuple[int, ...], r: dict) -> bool:
    """Feed-style range with optional si/se/ei/ee bounds."""
    for key, ok in (
        ("si", lambda c: c >= 0), ("se", lambda c: c > 0),
        ("ei", lambda c: c <= 0), ("ee", lambda c: c < 0),
    ):
        bound = r.get(key)
        if bound is None:
            continue
        parsed = _parse_version(bound)
        if parsed is None:
            return False  # unparseable bound: refuse to guess
        if not ok(_version_cmp(detected, parsed)):
            return False
    return True


def _cpe_products(cpes: list[str]) -> list[tuple[str, str]]:
    """nmap 'cpe:/a:vendor:product:version' -> [(vendor, product)]."""
    out = []
    for c in cpes or []:
        parts = c.split(":")
        if c.startswith("cpe:/a:") and len(parts) >= 4:
            out.append((parts[2], parts[3]))
        elif c.startswith("cpe:2.3:a:") and len(parts) >= 5:
            out.append((parts[3], parts[4]))
    return out


class CVEMatcher:
    """Loads the datasets once and matches them against scan results."""

    def __init__(self, config: dict):
        self.config = config
        cve_cfg = config.get("cve_matcher", {})
        self.enabled = cve_cfg.get("enabled", True)
        self.entries: list[dict[str, Any]] = []
        self.feed: list[dict[str, Any]] = []

        if not self.enabled:
            return

        db_path = Path(cve_cfg.get("db_path", "data/cve_db.json"))
        self.entries = self._load(db_path, "CVE database")
        feed_path = Path(cve_cfg.get("feed_path", "data/cve_feed.json"))
        if feed_path.exists():
            self.feed = self._load(feed_path, "CVE feed")
        else:
            logger.info(f"No CVE feed at {feed_path}; run `vulnforge.py cve-update` for broader coverage.")

    @staticmethod
    def _load(path: Path, label: str) -> list[dict]:
        if not path.exists():
            logger.warning(f"{label} not found at {path}")
            return []
        try:
            with open(path, encoding="utf-8") as f:
                entries = json.load(f).get("entries", [])
            logger.info(f"CVE matcher loaded {len(entries)} entries from {path}")
            return entries
        except Exception as exc:
            logger.error(f"Failed to load {label}: {exc}", exc_info=True)
            return []

    # ------------------------------------------------------------------
    def match_services(self, port_scan: dict) -> list[dict]:
        """
        Match every open port's product/version against the datasets.
        Returns finding dicts; each carries a 'confidence' level.
        """
        if not self.enabled or not (self.entries or self.feed):
            return []

        findings: list[dict] = []
        seen: set[tuple] = set()
        ports = port_scan.get("ports", {})

        for port_data in ports.values():
            if port_data.get("state") != "open":
                continue

            product = (port_data.get("product") or "").strip().lower()
            service = (port_data.get("service") or "").strip().lower()
            version_str = (port_data.get("version") or "").strip()
            haystack = f"{product} {service}".strip()
            cpes = _cpe_products(port_data.get("cpe", []))
            if not haystack and not cpes:
                continue

            detected = _parse_version(version_str)
            if detected is None:
                for c in port_data.get("cpe", []):  # nmap sometimes puts the version only in the CPE
                    ver = c.split(":")[4] if c.startswith("cpe:/") and len(c.split(":")) > 4 else ""
                    detected = _parse_version(ver) or detected
            packaged = looks_distro_packaged(version_str, port_data.get("extrainfo"), port_data.get("product"))

            for entry in self.entries:
                if not any(pm in haystack for pm in entry.get("product_match", [])):
                    continue
                if detected is None:
                    findings.append(self._build_finding(entry, port_data, version_str, "low"))
                    continue
                min_v = _parse_version(entry["min_version"]) if entry.get("min_version") else None
                max_v = _parse_version(entry["max_version"]) if entry.get("max_version") else None
                if min_v is not None and _version_cmp(detected, min_v) < 0:
                    continue
                if max_v is not None and _version_cmp(detected, max_v) >= 0:
                    continue
                seen.add((port_data.get("port"), entry["cve"]))
                findings.append(self._build_finding(entry, port_data, version_str, "medium" if packaged else "high"))

            if detected is None:
                continue  # the feed never guesses without a version
            for entry in self.feed:
                if (port_data.get("port"), entry["cve"]) in seen:
                    continue
                if not self._feed_product_matches(entry, cpes, haystack):
                    continue
                if not any(in_range(detected, r) for r in entry.get("ranges", [])):
                    continue
                seen.add((port_data.get("port"), entry["cve"]))
                # Backported fixes make pure version matches on distro builds unreliable;
                # only exploited-in-the-wild CVEs stay visible by default there.
                if packaged:
                    confidence = "medium" if entry.get("kev") else "low"
                else:
                    confidence = "high"
                findings.append(self._build_finding(entry, port_data, version_str, confidence))

        return findings

    @staticmethod
    def _feed_product_matches(entry: dict, cpes: list[tuple[str, str]], haystack: str) -> bool:
        product, vendor = entry.get("product", ""), entry.get("vendor", "")
        for cpe_vendor, cpe_product in cpes:
            if cpe_product != product:
                continue
            if product not in GENERIC_PRODUCTS:
                return True
            if cpe_vendor == vendor or VENDOR_ALIASES.get(cpe_vendor) == vendor:
                return True
        # No usable nmap CPE: fall back to the product name appearing in the banner.
        if not cpes:
            name = product.replace("_", " ")
            return product not in GENERIC_PRODUCTS and (name in haystack or product in haystack)
        return False

    @staticmethod
    def _build_finding(entry: dict, port_data: dict, version_str: str, confidence: str) -> dict:
        kev = bool(entry.get("kev"))
        name = entry.get("name") or entry.get("description", "Known CVE")[:80]
        title = f"{entry['cve']} — {name}"
        if kev:
            title += " [CISA KEV: exploited in the wild]"
        if confidence == "low" and not version_str:
            title += " (version undetected — unconfirmed)"
        elif confidence in ("medium", "low") and looks_distro_packaged(
            version_str, port_data.get("extrainfo"), port_data.get("product")
        ):
            title += " (version match only — distro backports possible)"

        poc = entry.get("public_poc") or {}
        description = entry.get("description", "")
        if poc:
            refs = ", ".join(f"{src}: {ref}" for src, ref in poc.items())
            description += f" A public exploit/PoC is known ({refs})."
        if entry.get("cvss"):
            description += f" CVSS {entry['cvss']}."

        evidence = (
            f"Port {port_data.get('port')}/{port_data.get('proto')} — "
            f"{port_data.get('product', '')} {version_str}".strip()
        )
        return {
            "title": title,
            "severity": entry.get("severity", "medium"),
            "description": description,
            "remediation": entry.get("remediation") or "Upgrade to a patched version; confirm against the vendor advisory.",
            "category": "cve_match",
            "evidence": evidence,
            "cve": entry["cve"],
            "public_poc": poc or None,
            "kev": kev,
            "confidence": confidence,
            "port": port_data.get("port"),
        }
